'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function allSplits(text, opts) {
  const whole = parse(text, opts);
  for (let i = 0; i <= text.length; i++) {
    for (let j = i; j <= text.length; j++) {
      const p = createParser(opts);
      const r = [...p.push(text.slice(0, i)), ...p.push(''), ...p.push(text.slice(i, j)), ...p.push(text.slice(j)), ...p.end()];
      assert.deepEqual(r, whole, JSON.stringify([text, i, j]));
    }
  }
  return whole;
}
function errLine(text, re) {
  for (let i = 0; i <= text.length; i++) {
    const p = createParser();
    assert.throws(() => { p.push(text.slice(0, i)); p.push(text.slice(i)); p.end(); }, e => e instanceof SyntaxError && re.test(e.message), JSON.stringify([text, i]));
  }
}

assert.deepEqual(allSplits(''), []);
assert.deepEqual(allSplits('\uFEFF'), []);
assert.deepEqual(allSplits('\n'), [['']]);
assert.deepEqual(allSplits('\n\n'), [[''], ['']]);
assert.deepEqual(allSplits('\r\n\r\n'), [[''], ['']]);
assert.deepEqual(allSplits('\r\r'), [[''], ['']]);
assert.deepEqual(allSplits('\uFEFFa,b\r\nc'), [['a', 'b'], ['c']]);
assert.deepEqual(allSplits('a,\uFEFF'), [['a', '\uFEFF']]);
assert.deepEqual(allSplits('a"b,"c""d"\r\n"x\r\ny",""\n'), [['a"b', 'c"d'], ['x\r\ny', '']]);
assert.deepEqual(allSplits('a;b,c\n', { delimiter: ';' }), [['a', 'b,c']]);
assert.deepEqual(allSplits('"","",'), [['', '', '']]);
assert.deepEqual(allSplits('"\ud83d\ude00"'), [['\ud83d\ude00']]);

// incremental emission
let p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
p = createParser();
assert.deepEqual(p.push(''), []);
assert.deepEqual(p.push('\uFEFFx'), []);
assert.deepEqual(p.end(), [['x']]);
p = createParser();
assert.deepEqual(p.push('x'), []);
assert.deepEqual(p.push('\uFEFF'), []);
assert.deepEqual(p.end(), [['x\uFEFF']]);

// errors
errLine('"a" ,b', /line 1\b/);
errLine('a\r\n"b\r\nc"x', /line 3\b/);
errLine('a\r\r"b\nc"d', /line 4\b/);
errLine('a\n"b\r\n', /line 3\b/);
errLine('"unterminated', /line 1\b/);
assert.throws(() => createParser().push(1), TypeError);
for (const d of ['"', '\r', '\n', '', ',,', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('a,a\n1', { header: true }), [{ a: '1', a_2: '' }]);
console.log('smoke ok');
